import{z as A,x as B,o as s,c as p,q as o,j as n,D as e,d as r,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"侦听与目录","description":"","frontmatter":{"title":"侦听与目录","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/snoop-vs-directory.md","filePath":"cs/snoop-vs-directory.md","lastUpdated":1791413859000}'),d={name:"cs/snoop-vs-directory.md"};function m(C,a,c,D,h,u){const t=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=o('<h1 id="侦听与目录" tabindex="-1">侦听与目录 <a class="header-anchor" href="#侦听与目录" aria-label="Permalink to &quot;侦听与目录&quot;">​</a></h1><div class="epigraph"><p>MESI 的状态机还要靠一种传播手段：每人听总线上所有事务，或向目录打听谁持有副本。</p><footer>—— 据 Censier and Feautrier, A New Solution to Coherence Problems in Multicache Systems, IEEE TC 1978；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/mesi-protocol">上一课</a>钉了 M/E/S/I 转换，并假定「每核看见总线上的读/写」。核数上升时广播先垮。<a href="/cs/multicore-shared-cache">多核与共享缓存</a>已把互连画成抽象。本课不重画四态。缺口是传播：窥探（snoop）对广播介质，目录把「谁有这行」记在主节点。本课只对照这两种，不写目录项的全部编码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窥探：每条 miss/upgrade 出现在共享总线或广播网上，所有 cache 控制器比较自己的标签并作答（提供数据、作废、降级）。正确性靠「人人看见同一全序事务」。缺口是带宽与监听过滤随核数线性涨——包含性 L3 只能过滤一部分。</p><p>目录：每行有一个家节点，存位向量或链表：哪些核可能有副本。请求先到家，家只向有副本的核发点对点消息。无广播，但多一跳延迟，且目录本身要存储。</p><p><span class="marginnote">直觉类比：窥探像微信群发——每个人都得看一眼、回一句「与我无关」；目录像问总台——先查登记簿，只给真正持有副本的人打电话。核少时群发快（一跳人人知道），核多时总台省带宽（只联系持有人），代价是多一跳延迟加一份要维护的登记簿。</span></p><p><span class="marginnote">Censier–Feautrier 1978 给出目录方案的早期完整表述。总线窥探与 Illinois MESI 同一时代，对象是小规模对称多处理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>窥探实现：总线仲裁给出全局序；写升级等待所有 snoop 响应。监听过滤器、包含 LLC 用来减少 L1 被问的次数。</p><p>目录实现：数据请求 → 目录；若行在 M，转发到持有者，持有者写回或直接给请求者，目录更新位向量。替换通知目录（或用超时/静默替换加后续探测）。</p>',11)),(s(),n(l,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E6%9F%90%E6%A0%B8%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20BUS%5B%22%E7%AA%A5%E6%8E%A2%EF%BC%9A%E5%B9%BF%E6%92%AD%E7%BB%99%E6%89%80%E6%9C%89%E4%BA%BA%22%5D%0A%20%20MISS%20--%3E%20DIR%5B%22%E7%9B%AE%E5%BD%95%EF%BC%9A%E9%97%AE%E5%AE%B6%E8%8A%82%E7%82%B9%22%5D%0A%20%20DIR%20--%3E%20P2P%5B%22%E5%8F%AA%E9%80%9A%E7%9F%A5%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"两种都实现同一套 MESI 不变式；变的是消息条数与延迟分档。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：64 核机器上，位向量按核记位，一个目录项只多 8 个字节；而窥探要每条缺失都打扰其余 63 个核的控制器。核数翻到 128，广播的条数还在线性涨、总线带宽却不涨——这正是大规模芯片几乎都换目录方案的账面理由。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"窥探的「最近写」由总线序定义。目录的「最近写」由家节点序列化到该行的请求定义——同一行仍有全序，不同行之间的序是存储模型的事，下一课。",-1)),(s(),n(l,null,{default:e(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B8%20C%20%E5%AF%B9%E6%9F%90%E8%A1%8C%E5%8F%91%E8%AF%BB%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20H%5B%22%E5%85%88%E5%88%B0%E8%AF%A5%E8%A1%8C%E7%9A%84%E5%AE%B6%E8%8A%82%E7%82%B9%E7%9B%AE%E5%BD%95%22%5D%0A%20%20H%20--%3E%20S%7B%22%E6%9F%A5%E4%BD%8D%E5%90%91%E9%87%8F%3A%20%E8%B0%81%E6%8C%81%E6%9C%89%E5%89%AF%E6%9C%AC%3F%22%7D%0A%20%20S%20--%20%22%E6%97%A0%E4%BA%BA%E6%8C%81%E6%9C%89%22%20--%3E%20M%5B%22%E4%BB%8E%E5%86%85%E5%AD%98%E5%8F%96%E6%95%B0%20%E5%9B%9E%E7%BB%99%20C%20%E5%B9%B6%E7%99%BB%E8%AE%B0%20C%22%5D%0A%20%20S%20--%20%22%E6%9C%89%E4%BA%BA%E4%B8%94%E5%A4%84%E4%BA%8E%20M%22%20--%3E%20F%5B%22%E8%AF%B7%E6%8C%81%E6%9C%89%E8%80%85%E5%86%99%E5%9B%9E%E6%88%96%E7%9B%B4%E6%8E%A5%E8%BD%AC%E5%8F%91%22%5D%0A%20%20F%20--%3E%20U%5B%22%E6%9B%B4%E6%96%B0%E4%BD%8D%E5%90%91%E9%87%8F%20%E9%99%8D%E7%BA%A7%E6%97%A7%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A%20%20M%20--%3E%20D%5B%22C%20%E6%8B%BF%E5%88%B0%E6%95%B0%E6%8D%AE%22%5D%0A%20%20U%20--%3E%20D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">这张图回答「目录协议一次读请求到底走几步」：请求先到家里查登记，再按持有情况分岔——干净时一次内存读就完，脏时还要惊动旧持有者写回。与窥探「一嗓子喊全屋」相比，每一步都是点对点，消息条数从 \\(O(n)\\) 降到 \\(O(1)\\) 上下。</span></p><p>NUMA：目录切片跟内存走，远程行必经互连。窥探很难跨太多芯片。包含层次与目录可叠加：LLC 当本节点过滤器。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MOESI 的 Owned 作为传播优化（脏共享不写回内存），不把具体互联协议当正文。也不把目录当成操作系统页表：粒度是 cache 行，由硬件维护。存储一致性模型（SC/TSO）下一课才问多地址交错。</p><p><span class="marginnote">常见误区：把目录当成软件层的页表。目录项的粒度是 cache 行、由硬件在纳秒级维护，操作系统完全看不见它，它也不管虚拟地址翻译。另外目录不是「处处变慢」——本地行照旧，只有跨节点的行才多付那一跳。</span></p><p>后课默认：小规模用窥探，大规模用目录；MESI 状态仍适用。程序员问「两条 store 他核怎么看见」，要另加模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窥探靠广播与人人监听；目录靠家节点与点对点。</li><li>不变式仍是 MESI；变的是可扩展性与延迟。</li><li>多地址上的可见顺序是下一课存储模型。</li><li>出处：Censier and Feautrier, <em>IEEE TC</em>, 1978；Papamarcos and Patel, <em>ISCA</em>, 1984；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const f=A(d,[["render",m]]);export{F as __pageData,f as default};
